      "evidence_ref": "S0017",
      "role": "assistant"
    },
    {
      "content": "4. Checker user reviews the labels that have been placed on the document by the Tagger user.\n",
      "evidence_ref": "S0018",
      "role": "assistant"
    },
    {
      "content": "5. Checker user approves or rejects each label as needed.\n",
      "evidence_ref": "S0019",
      "role": "assistant"
